{
  "schemaVersion": "3",
  "kind": "mixin",
  "name": "audit-mixin-cred",
  "displayName": "Audit mixin credential",
  "description": "Test mixin of the docker-sbx audit, declares an optional credential of a service sbx does not know, injected into a host that never resolves.",
  "sandbox": {
    "image": "sbx-kit-src:spec-588c26b42499"
  },
  "permissions": {
    "network": {
      "allow": [
        "api.audit.invalid:443"
      ]
    }
  },
  "credentials": [
    {
      "service": "audit-svc",
      "description": "Dummy credential of the audit",
      "apiKey": {
        "name": "",
        "inject": [
          {
            "domain": "api.audit.invalid",
            "header": "X-Audit-Key",
            "format": "%s"
          }
        ]
      }
    }
  ]
}
